import 'package:flutter_overboard/flutter_overboard.dart';

final pages = [
  PageModel(
    color: const Color(0xFF0097A7),
    imageAssetPath: 'assets/01.png',
    title: 'Screen 1',
    body: 'Share your ideas with the team',
    doAnimateImage: true,
  ),
];

OverBoard(
  pages: pages,
  showBullets: true,
  skipCallback: () => print('Skip'),
  finishCallback: () => print('Finish'),
);
